import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createServer,type Server} from 'node:http';
import {once} from 'node:events';
import {readFile,mkdtemp,rm,readdir,mkdir,writeFile,symlink,truncate} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {DesktopAdapter,DesktopAdapterError} from '../src/browser/desktop-adapter.js';
import {WebDriverClient} from '../src/browser/webdriver-client.js';
import type {Config} from '../src/config/config.js';

const png=await readFile(new URL('./fixtures/tauri-app/src-tauri/icons/icon.png',import.meta.url));
async function serve(handler:(url:string,method:string,res:import('node:http').ServerResponse)=>void){const server=createServer((req,res)=>handler(req.url??'',req.method??'',res));server.listen(0,'127.0.0.1');await once(server,'listening');return{server,port:(server.address() as {port:number}).port};}
function config(endpoint:string,session='bearer-like-session'):Config{return{provider:'desktop',project:{id:'attach-test',name:'attach test',base_url:'http://127.0.0.1'},browser:{headless:true,viewport:{width:800,height:600},allowed_origins:[]},desktop:{automation:{endpoint,session_id:session},visual:{},window:{screenshot_mode:'webview'}}} as unknown as Config;}
test('desktop adapter lazily attaches with GET screenshot and detach never deletes',async()=>{
  let calls:Array<{url:string;method:string}>=[];const fixture=await serve((url,method,res)=>{calls.push({url,method});res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:url.endsWith('/screenshot')?png.toString('base64'):'http://127.0.0.1/page'}));});
  const root=await mkdtemp(path.join(os.tmpdir(),'umb-attach-'));const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`),root);
   try{await adapter.start();assert.deepEqual(calls,[]);const shot=await adapter.captureScreenshotBytes({kind:'webview'});assert.equal(shot.captureKind,'webview');assert.equal(shot.image.subarray(0,8).toString('hex'),'89504e470d0a1a0a');assert.deepEqual(await readdir(root),[],'raw capture does not persist artifacts');assert.deepEqual(calls.map(c=>c.method),['GET','GET','GET']);assert.ok(calls[1]!.url.includes('/session/bearer-like-session/screenshot'));await assert.rejects(adapter.takeScreenshot(false),error=>error instanceof DesktopAdapterError&&error.code==='CAPABILITY_UNAVAILABLE');await assert.rejects(adapter.takeScreenshot({kind:'webview'}),error=>error instanceof DesktopAdapterError&&error.code==='PERSISTENCE_ERROR');await adapter.close();assert.deepEqual(calls.map(c=>c.method),['GET','GET','GET']);assert.equal(calls.some(c=>c.method==='DELETE'),false);await assert.rejects(adapter.captureScreenshotBytes({kind:'webview'}),/ATTACHMENT_UNAVAILABLE/);}
  finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));await rm(root,{recursive:true,force:true});}
});
test('desktop adapter rejects DNS loopback aliases, redirects, missing sessions, and window capture',async()=>{
  assert.throws(()=>new DesktopAdapter(config('http://localhost:4444')),/INVALID_ADAPTER_CONFIG/);
  let redirected=false;const target=await serve((_u,_m,res)=>{redirected=true;res.end('{}');});const redirect=await serve((_u,_m,res)=>{res.writeHead(302,{location:`http://127.0.0.1:${target.port}/x`}).end();});
   const missing=await serve((_u,_m,res)=>res.writeHead(404,{'content-type':'application/json'}).end(JSON.stringify({value:{error:'invalid session id',message:'private raw response'}})));const unknown=await serve((_u,_m,res)=>res.writeHead(404,{'content-type':'application/json'}).end(JSON.stringify({value:{error:'unknown command',message:'private raw response'}})));const root=await mkdtemp(path.join(os.tmpdir(),'umb-attach-errors-'));
  try{
     const redirectedAdapter=new DesktopAdapter(config(`http://127.0.0.1:${redirect.port}`));await assert.rejects(redirectedAdapter.captureScreenshotBytes({kind:'webview'}),/ATTACHMENT_UNAVAILABLE/);assert.equal(redirected,false);
      const absent=new DesktopAdapter(config(`http://127.0.0.1:${missing.port}`,'secret-session-id'));await assert.rejects(absent.captureScreenshotBytes({kind:'webview'}),error=>error instanceof DesktopAdapterError&&error.code==='SESSION_NOT_FOUND'&&!error.message.includes('secret-session-id')&&!error.message.includes('private raw response'));
       const unknownRoute=new DesktopAdapter(config(`http://127.0.0.1:${unknown.port}`));await assert.rejects(unknownRoute.captureScreenshotBytes({kind:'webview'}),error=>error instanceof DesktopAdapterError&&error.code==='CAPABILITY_UNAVAILABLE'&&!error.message.includes('private raw response'));
    await assert.rejects(absent.takeScreenshot({kind:'window'}),error=>error instanceof DesktopAdapterError&&error.code==='CAPABILITY_UNAVAILABLE');
   }finally{await Promise.all([redirect.server,target.server,missing.server,unknown.server].map(server=>new Promise<void>(resolve=>server.close(()=>resolve()))));await rm(root,{recursive:true,force:true});}
 });

test('attached screenshot validates complete PNG structure before persisting any artifact',async()=>{
  const cases=[Buffer.from('89504e470d0a1a0a','hex'),png.subarray(0,32),(()=>{const bad=Buffer.from(png);bad.writeUInt32BE(0,16);return bad;})()];
  for(const bytes of cases){const fixture=await serve((url,_m,res)=>res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:url.endsWith('/screenshot')?bytes.toString('base64'):'http://127.0.0.1/page'}))),root=await mkdtemp(path.join(os.tmpdir(),'umb-attach-invalid-png-')),adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`),root);try{await assert.rejects(adapter.captureScreenshotBytes({kind:'webview'}),error=>error instanceof DesktopAdapterError&&error.code==='REMOTE_COMMAND_FAILED');assert.deepEqual(await readdir(root),[]);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));await rm(root,{recursive:true,force:true});}}
});

test('trusted attached navigation uses W3C calls, checks final origin, and latches without lifecycle calls',async()=>{
  const calls:string[]=[];let current='http://127.0.0.1/start';
  const fixture=await serve((_url,_method,res)=>res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:null})));
  // Read the navigation payload from the request stream in this tiny fixture.
  fixture.server.removeAllListeners('request');
  fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',x=>chunks.push(x));req.on('end',()=>{const url=req.url??'';calls.push(`${req.method} ${url}`);if(url.endsWith('/url')&&req.method==='POST')current=String(JSON.parse(Buffer.concat(chunks).toString()).url);const value=url.endsWith('/url')?current:url.endsWith('/title')?'fixture':false;res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});
  const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));
  try{const status=await adapter.navigate('http://127.0.0.1/next','load');assert.equal(status.url,'http://127.0.0.1/next');assert.equal(adapter.currentUrl(),status.url);assert.ok(calls.includes(`POST /session/bearer-like-session/url`));assert.equal(calls.some(x=>x.startsWith('DELETE ')),false);current='https://outside.example/';await assert.rejects(adapter.status(),/latched out-of-policy/);const count=calls.length;await assert.rejects(adapter.captureScreenshotBytes({kind:'webview'}),/latched out-of-policy/);await assert.rejects(adapter.back(),/latched out-of-policy/);assert.equal(calls.length,count);assert.equal(calls.some(x=>x.startsWith('DELETE ')),false);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
});

test('attached actions serialize element refs, encode named keys, and enforce action bounds',async()=>{
  const calls:Array<{method:string;url:string;body:any}>=[];const fixture=await serve((_u,_m,res)=>res.end());fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',x=>chunks.push(x));req.on('end',()=>{const body=chunks.length?JSON.parse(Buffer.concat(chunks).toString()):undefined,url=req.url??'';calls.push({method:req.method??'',url,body});let value:any=null;if(url.endsWith('/url'))value='http://127.0.0.1/page';else if(url.endsWith('/title'))value='ok';else if(url.endsWith('/elements'))value=[{'element-6066-11e4-a52e-4f735466cecf':'element-1'}];else if(url.endsWith('/displayed')||url.endsWith('/enabled'))value=true;else if(url.endsWith('/execute/sync'))value=body.script.includes('valid')?{valid:true,enabled:true}:true;res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});
  const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await adapter.act('select',{by:'css',value:'select'},'choice');const select=calls.find(c=>c.url.endsWith('/execute/sync'))!;assert.deepEqual(select.body.args[0],{'element-6066-11e4-a52e-4f735466cecf':'element-1'});assert.equal(adapter.revision,1);assert.equal(adapter.actionSequence()[0]!.revision,1);await adapter.keyboard('ENTER',{by:'css',value:'input'});const keyCall=calls.find(c=>c.url.endsWith('/element/element-1/value'))!;assert.deepEqual(keyCall.body.value,['\uE007']);await assert.rejects(adapter.type({by:'css',value:'input'},'x'.repeat(10001)),/bounds/);await assert.rejects(adapter.scroll('sideways',2),/invalid/);assert.equal(calls.some(c=>c.method==='DELETE'||c.url==='/session'),false);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
});

test('screenshot refuses an initially disallowed origin before requesting bytes',async()=>{
  const calls:string[]=[];const fixture=await serve((url,_method,res)=>{calls.push(url);res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:'https://outside.example/private?token=secret'}));});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await assert.rejects(adapter.captureScreenshotBytes({kind:'webview'}),/latched out-of-policy/);assert.equal(calls.some(url=>url.endsWith('/screenshot')),false);await assert.rejects(adapter.captureScreenshotBytes({kind:'webview'}),/latched out-of-policy/);assert.equal(calls.length,1);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
});

test('waitFor uses the 5000 ms default and validates explicit 1..30000 ms budgets',async()=>{
  const started=Date.now();const fixture=await serve((url,_method,res)=>{const ready=Date.now()-started>=1100;const value=url.endsWith('/url')?(ready?'http://127.0.0.1/target':'http://127.0.0.1/initial'):'fixture';res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{const status=await adapter.waitFor('url','/target');assert.ok(Date.now()-started>=1000,'default wait budget must exceed the former 1000 ms default');assert.equal(status.url,'http://127.0.0.1/target');await assert.rejects(adapter.waitFor('url','missing',0),/1 and 30000/);await assert.rejects(adapter.waitFor('url','missing',30001),/1 and 30000/);await assert.rejects(adapter.waitFor('url','missing',1),/timed out/);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
});

test('URL wait polls sanitized status on one read-only deadline',async()=>{
  const requests:Array<{method:string;url:string;body:any}>=[],base='/session/bearer-like-session';let current='https://user:password@safe.example/start?token=QUERY_SECRET#FRAGMENT_SECRET',urlReads=0,matchAfter=1,stallTitle=false;
  const fixture=await serve((_url,_method,res)=>res.end('{}'));fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',chunk=>chunks.push(chunk));req.on('end',()=>{const url=req.url??'',method=req.method??'',body=chunks.length?JSON.parse(Buffer.concat(chunks).toString()):undefined;requests.push({method,url,body});let value:any=null;if(url.endsWith('/url')){urlReads++;if(urlReads>=matchAfter)current='https://user:password@safe.example/ReadyCase?token=QUERY_SECRET#FRAGMENT_SECRET';value=current;}else if(url.endsWith('/title')){if(stallTitle){res.writeHead(200,{'content-type':'application/json'});res.flushHeaders();return;}value='Fixed harmless title';}else if(url.endsWith('/execute/sync'))value=false;res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});const adapterConfig=config(`http://127.0.0.1:${fixture.port}`);adapterConfig.browser.allowed_origins=['https://safe.example'];const adapter=new DesktopAdapter(adapterConfig);
  try{
    const immediate=await adapter.waitFor('url','/ReadyCase');assert.deepEqual(immediate,{url:'https://safe.example/ReadyCase',title:'Fixed harmless title',tabId:'webdriver-current',loading:false,pendingDialog:null,lastPageError:null,revision:0,viewport:null});assert.deepEqual(requests.map(({method,url})=>`${method} ${url}`),[`GET ${base}/url`,`GET ${base}/title`,`POST ${base}/execute/sync`]);assert.deepEqual(requests[2]?.body,{script:'return document.readyState !== "complete"',args:[]});assert.doesNotMatch(JSON.stringify(immediate),/QUERY_SECRET|FRAGMENT_SECRET|password/);
    requests.length=0;urlReads=0;matchAfter=3;current='https://user:password@safe.example/start?token=QUERY_SECRET#FRAGMENT_SECRET';const delayed=await adapter.waitFor('url','/ReadyCase',1000);assert.equal(delayed.url,'https://safe.example/ReadyCase');assert.equal(delayed.title,'Fixed harmless title');assert.equal(urlReads,3);assert.deepEqual(requests.map(({method,url})=>`${method} ${url}`),Array.from({length:3},()=>[`GET ${base}/url`,`GET ${base}/title`,`POST ${base}/execute/sync`]).flat());
    requests.length=0;urlReads=0;matchAfter=Infinity;const start=Date.now();await assert.rejects(adapter.waitFor('url','/never',125),error=>error instanceof DesktopAdapterError&&error.code==='REMOTE_COMMAND_FAILED'&&['REMOTE_COMMAND_FAILED: wait condition timed out','REMOTE_COMMAND_FAILED: operation timed out: deadline exceeded'].includes(error.message));assert.ok(Date.now()-start<600,'125 ms wait remains bounded under suite load');assert.ok(urlReads>=1&&urlReads<8,'polling stays within the shared wait deadline');
     requests.length=0;stallTitle=true;const stalledAt=Date.now();await assert.rejects(adapter.waitFor('url','/never',100),error=>error instanceof DesktopAdapterError&&error.code==='REMOTE_COMMAND_FAILED'&&['REMOTE_COMMAND_FAILED: wait condition timed out','REMOTE_COMMAND_FAILED: operation timed out: deadline exceeded'].includes(error.message));assert.ok(Date.now()-stalledAt<600,'a stalled status read is bounded by the overall deadline');assert.deepEqual(requests.map(({method,url})=>`${method} ${url}`),[`GET ${base}/url`,`GET ${base}/title`],'stalled read is not retried and no readiness script follows');assert.equal(adapter.revision,0);assert.deepEqual(adapter.actionSequence(),[]);assert.equal(requests.some(({method,url})=>method==='DELETE'||/\/window|\/context|\/screenshot|\/click|\/actions|\/refresh/.test(url)||method==='POST'&&url.endsWith('/url')),false,'URL waits issue no mutation, screenshot, context/window, navigation, or lifecycle routes');
  }finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
});

test('origin policy canonicalizes tauri origins and rejects other, opaque, file, and data URLs with a latch',async()=>{
  const fixture=await serve((url,_method,res)=>{const value=url.endsWith('/url')?'tauri://localhost/screen':url.endsWith('/title')?'fixture':false;res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});const tauriConfig=config(`http://127.0.0.1:${fixture.port}`);tauriConfig.project.base_url='tauri://localhost';const accepted=new DesktopAdapter(tauriConfig);try{assert.equal((await accepted.status()).url,'tauri://localhost/screen');}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
  for(const remote of ['tauri://other-host/page','https://localhost/page','data:text/html,private','file:///tmp/page']){let requests=0;const denied=await serve((url,_method,res)=>{requests++;const value=url.endsWith('/url')?remote:'unexpected';res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});const c=config(`http://127.0.0.1:${denied.port}`);c.project.base_url='tauri://localhost';const adapter=new DesktopAdapter(c);try{await assert.rejects(adapter.status(),/latched out-of-policy/);assert.equal(requests,1,`${remote} should be rejected immediately after URL observation`);await assert.rejects(adapter.find({by:'css',value:'body'}),/latched out-of-policy/);assert.equal(requests,1,'latched adapter must not make further requests');}finally{await new Promise<void>(resolve=>denied.server.close(()=>resolve()));}}
  const http=await serve((url,_method,res)=>res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:url.endsWith('/url')?'http://127.0.0.1/page':'fixture'})));const httpConfig=config(`http://127.0.0.1:${http.port}`);httpConfig.project.base_url='http://127.0.0.1:80';try{assert.equal((await new DesktopAdapter(httpConfig).status()).url,'http://127.0.0.1/page');}finally{await new Promise<void>(resolve=>http.server.close(()=>resolve()));}
});

test('full-page attached screenshots are explicitly unavailable',async()=>{let calls=0;const fixture=await serve((_url,_method,res)=>{calls++;res.end('{}');});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await assert.rejects(adapter.captureScreenshotBytes({kind:'webview',fullPage:true}),/full-page/);assert.equal(calls,0);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}});

test('attached status reports only valid CSS viewport measurements with read-only WebDriver commands',async()=>{
  const requests:Array<{method:string;url:string;body:any}>=[];let viewportValue:any={width:1024,height:768},viewportFailure=false;const fixture=await serve((_url,_method,res)=>res.end('{}'));fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',chunk=>chunks.push(chunk));req.on('end',()=>{const url=req.url??'',method=req.method??'',body=chunks.length?JSON.parse(Buffer.concat(chunks).toString()):undefined;requests.push({method,url,body});let value:any=null;if(url.endsWith('/url'))value='http://127.0.0.1/page';else if(url.endsWith('/title'))value='fixture';else if(url.endsWith('/execute/sync')){if(body.script==='return document.readyState !== "complete"')value=false;else if(body.script==='return {width:window.innerWidth,height:window.innerHeight}')value=viewportValue;}if(viewportFailure&&url.endsWith('/execute/sync')&&body.script==='return {width:window.innerWidth,height:window.innerHeight}')res.writeHead(500,{'content-type':'application/json'}).end(JSON.stringify({value:{error:'unsupported operation',message:'private driver detail'}}));else res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`)),base='/session/bearer-like-session';
  try{
    const status=await adapter.status();assert.deepEqual(status.viewport,{width:1024,height:768});assert.equal(status.loading,false);assert.deepEqual(requests.map(({method,url})=>`${method} ${url}`),[`GET ${base}/url`,`GET ${base}/title`,`POST ${base}/execute/sync`,`POST ${base}/execute/sync`]);assert.deepEqual(requests.filter(request=>request.url.endsWith('/execute/sync')).map(request=>request.body),[{script:'return document.readyState !== "complete"',args:[]},{script:'return {width:window.innerWidth,height:window.innerHeight}',args:[]}]);
    for(const invalid of [{},null,'1024x768',[],{width:0,height:768},{width:-1,height:768},{width:1024.5,height:768},{width:1024,height:0},{width:1024,height:-1},{width:1024,height:768.5},{width:Number.MAX_SAFE_INTEGER+1,height:768}]){viewportValue=invalid;assert.equal((await adapter.status()).viewport,null,`invalid measurement ${JSON.stringify(invalid)} must not be reported`);}
    viewportFailure=true;assert.equal((await adapter.status()).viewport,null,'status preserves fallback behavior when viewport measurement is unavailable');
    assert.equal(requests.some(({method,url})=>method==='DELETE'||url.endsWith('/window/rect')||url.endsWith('/window/size')||url.endsWith('/url')&&method==='POST'||url.endsWith('/refresh')),false,'status must not mutate window, navigate, refresh, or change session lifecycle');assert.equal(adapter.revision,0);assert.deepEqual(adapter.actionSequence(),[]);
  }finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
});

