    requests.length=0;await assert.rejects(adapter.waitFor('enabled',{by:'css',value:'#stale-enabled'},500));assert.equal(requests.filter(request=>request.url.endsWith('/element/stale-enabled/enabled')).length,1,'a stale enabled-state error fails without retry');
