test('wait hidden accepts absent/unique hidden targets but detached requires zero matches',async()=>{const fixture=await serve((url,_method,res)=>{let value:any=null;if(url.endsWith('/url'))value='http://127.0.0.1/page';else if(url.endsWith('/title'))value='fixture';else if(url.endsWith('/elements')){const body=(res as any).req;void body;value=[];}else if(url.endsWith('/displayed'))value=false;res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',x=>chunks.push(x));req.on('end',()=>{const url=req.url??'',body=chunks.length?JSON.parse(Buffer.concat(chunks).toString()):undefined;let value:any=null;if(url.endsWith('/url'))value='http://127.0.0.1/page';else if(url.endsWith('/title'))value='fixture';else if(url.endsWith('/elements'))value=body.value==='#hidden'?[{'element-6066-11e4-a52e-4f735466cecf':'hidden'}]:[];else if(url.endsWith('/displayed'))value=false;res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await adapter.waitFor('detached',{by:'css',value:'#absent'},100);await adapter.waitFor('hidden',{by:'css',value:'#absent'},100);await adapter.waitFor('hidden',{by:'css',value:'#hidden'},100);await assert.rejects(adapter.waitFor('detached',{by:'css',value:'#hidden'},100),/timed out/);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}});

test('select refuses disabled select and disabled option before mutation',async()=>{for(const reason of ['disabled-select','disabled-option']){const calls:Array<{url:string;body:any}>=[];const fixture=await serve((_u,_m,res)=>res.end());fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',x=>chunks.push(x));req.on('end',()=>{const url=req.url??'',body=chunks.length?JSON.parse(Buffer.concat(chunks).toString()):undefined;calls.push({url,body});let value:any=null;if(url.endsWith('/url'))value='http://127.0.0.1/page';else if(url.endsWith('/elements'))value=[{'element-6066-11e4-a52e-4f735466cecf':'select-1'}];else if(url.endsWith('/displayed'))value=true;else if(url.endsWith('/execute/sync'))value={valid:true,enabled:false,reason};res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await assert.rejects(adapter.act('select',{by:'css',value:'select'},'chosen'),/disabled/);assert.equal(calls.filter(x=>x.url.endsWith('/execute/sync')).length,1,'only read-only enabled/option precheck should run');}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}}});

test('truncated click response is indeterminate and is never retried',async()=>{let clicks=0;const fixture=await serve((url,_method,res)=>{if(url.endsWith('/url'))res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:'http://127.0.0.1/page'}));else if(url.endsWith('/elements'))res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:[{'element-6066-11e4-a52e-4f735466cecf':'target'}]}));else if(url.endsWith('/displayed'))res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:true}));else if(url.endsWith('/click')){clicks++;res.writeHead(200,{'content-type':'application/json'}).write('{"value":');res.socket?.destroy();}else res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:'fixture'}));});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await assert.rejects(adapter.act('click',{by:'css',value:'#go'}),error=>error instanceof DesktopAdapterError&&error.code==='INDETERMINATE_MUTATION');assert.equal(clicks,1);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}});

test('navigation remains bounded when deadline expires after dispatch during postcheck',async()=>{let urls=0,dispatches=0;const fixture=await serve((url,method,res)=>{let value:any='fixture',delay=0;if(url.endsWith('/url')&&method==='GET'){urls++;value='http://127.0.0.1/page';delay=urls>=3?500:10;}else if(url.endsWith('/url')&&method==='POST'){dispatches++;value=null;delay=10;}setTimeout(()=>res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value})),delay);});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));const started=Date.now();try{await assert.rejects(adapter.navigate('/next','load',200),error=>error instanceof DesktopAdapterError&&error.code==='INDETERMINATE_MUTATION');assert.equal(dispatches,1);assert.ok(Date.now()-started<350,'postcheck must share navigation deadline');}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}});

