test('allowed navigation whose postcheck observes foreign origin latches without restoring or detaching',async()=>{const calls:string[]=[];let current='http://127.0.0.1/start';const fixture=await serve((_url,_method,res)=>res.end());fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',chunk=>chunks.push(chunk));req.on('end',()=>{const url=req.url??'',method=req.method??'';calls.push(`${method} ${url}`);if(method==='POST'&&url.endsWith('/url'))current='https://outside.example/';res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:url.endsWith('/url')?current:null}));});});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await assert.rejects(adapter.navigate('/allowed','load'),/latched out-of-policy/);assert.deepEqual(calls,['GET /session/bearer-like-session/url','GET /session/bearer-like-session/url','POST /session/bearer-like-session/url','GET /session/bearer-like-session/url']);assert.equal(calls.some(call=>call.startsWith('DELETE ')),false);await assert.rejects(adapter.back(),/latched out-of-policy/);assert.equal(calls.length,4);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}});

test('fill does not retry send-keys after clear completed and records only the clear',async()=>{const calls:string[]=[];let remoteValue='original';const fixture=await serve((_url,_method,res)=>res.end());fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',chunk=>chunks.push(chunk));req.on('end',()=>{const url=req.url??'',method=req.method??'';calls.push(`${method} ${url}`);let value:any=null;if(url.endsWith('/url'))value='http://127.0.0.1/page';else if(url.endsWith('/elements'))value=[{'element-6066-11e4-a52e-4f735466cecf':'input'}];else if(url.endsWith('/displayed'))value=true;else if(url.endsWith('/clear'))remoteValue='';else if(url.endsWith('/value'))value={error:'timeout',message:'private fixture failure'};res.writeHead(url.endsWith('/value')?500:200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`));try{await assert.rejects(adapter.act('fill',{by:'css',value:'input'},'replacement'),error=>error instanceof DesktopAdapterError&&error.code==='INDETERMINATE_MUTATION'&&!error.message.includes('private'));assert.equal(remoteValue,'','successful clear may leave remote state cleared');assert.deepEqual(calls.filter(call=>call.endsWith('/clear')||call.endsWith('/value')),['POST /session/bearer-like-session/element/input/clear','POST /session/bearer-like-session/element/input/value']);assert.equal(calls.filter(call=>call.endsWith('/value')).length,1,'dispatched send-keys is never retried');assert.equal(adapter.revision,1);assert.equal(adapter.actionSequence().length,1);assert.equal(adapter.actionSequence()[0]!.action,'fill-clear');}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}});

test('upload rejects traversal, outside symlink, directory, and oversized files before element mutation',async()=>{const root=await mkdtemp(path.join(os.tmpdir(),'umb-upload-root-')),outside=await mkdtemp(path.join(os.tmpdir(),'umb-upload-outside-'));const calls:string[]=[];const fixture=await serve((url,method,res)=>{calls.push(`${method} ${url}`);res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value:url.endsWith('/url')?'http://127.0.0.1/page':'unexpected'}));});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`),root);try{await writeFile(path.join(outside,'secret.txt'),'secret');await symlink(path.join(outside,'secret.txt'),path.join(root,'outside-link'));await mkdir(path.join(root,'directory'));await writeFile(path.join(root,'oversized.bin'),Buffer.alloc(0));await truncate(path.join(root,'oversized.bin'),20*1024*1024+1);for(const file of ['../secret.txt','outside-link','directory','oversized.bin']){const before=calls.length;await assert.rejects(adapter.upload({by:'css',value:'input'},file));assert.equal(calls.slice(before).some(call=>call.includes('/element/')||call.endsWith('/execute/sync')),false,`${file} must be rejected before remote element access or mutation`);}assert.equal(calls.some(call=>call.endsWith('/value')),false);assert.equal(calls.some(call=>call.startsWith('DELETE ')),false);}finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));await Promise.all([rm(root,{recursive:true,force:true}),rm(outside,{recursive:true,force:true})]);}});

test('hidden waits accept absent or unique hidden targets, poll transitions, and reject ambiguity/stale probes without side effects',async()=>{
  const requests:Array<{method:string;url:string;body:any}>=[],allRequests:Array<{method:string;url:string;body:any}>=[],polls=new Map<string,number>(),transitionStates:boolean[]=[];const fixture=await serve((_url,_method,res)=>res.end('{}'));fixture.server.removeAllListeners('request');fixture.server.on('request',(req,res)=>{const chunks:Buffer[]=[];req.on('data',chunk=>chunks.push(chunk));req.on('end',()=>{const url=req.url??'',method=req.method??'',body=chunks.length?JSON.parse(Buffer.concat(chunks).toString()):undefined,request={method,url,body};requests.push(request);allRequests.push(request);let value:any=null;if(url.endsWith('/url'))value='http://127.0.0.1/page';else if(url.endsWith('/title'))value='fixture';else if(url.endsWith('/elements')){const selector=body.value,count=polls.get(selector)??0;polls.set(selector,count+1);if(selector==='#unique-hidden')value=[{'element-6066-11e4-a52e-4f735466cecf':'hidden'}];else if(selector==='#transition')value=[{'element-6066-11e4-a52e-4f735466cecf':'transition'}];else if(selector==='#duplicates')value=[{'element-6066-11e4-a52e-4f735466cecf':'one'},{'element-6066-11e4-a52e-4f735466cecf':'two'}];else if(selector==='#stale')value=[{'element-6066-11e4-a52e-4f735466cecf':'stale'}];else value=[];}else if(url.endsWith('/element/hidden/displayed'))value=false;else if(url.endsWith('/element/transition/displayed')){value=(polls.get('#transition')??0)<3;transitionStates.push(value);}else if(url.endsWith('/element/stale/displayed')){res.writeHead(404,{'content-type':'application/json'}).end(JSON.stringify({value:{error:'stale element reference',message:'fixture race'}}));return;}else if(url.endsWith('/execute/sync'))value=false;res.writeHead(200,{'content-type':'application/json'}).end(JSON.stringify({value}));});});const adapter=new DesktopAdapter(config(`http://127.0.0.1:${fixture.port}`)),base='/session/bearer-like-session';
  try{
    await adapter.waitFor('hidden',{by:'css',value:'#absent'},500);assert.equal(polls.get('#absent'),1,'zero matches pass on their first observation');assert.deepEqual(requests.map(({method,url})=>`${method} ${url}`),[`GET ${base}/url`,`POST ${base}/elements`,`GET ${base}/url`,`GET ${base}/title`,`POST ${base}/execute/sync`]);assert.deepEqual(requests.filter(request=>request.url.endsWith('/elements')).map(request=>request.body),[{using:'css selector',value:'#absent'}]);
    requests.length=0;await adapter.waitFor('hidden',{by:'css',value:'#unique-hidden'},500);assert.deepEqual(requests.map(({method,url})=>`${method} ${url}`),[`GET ${base}/url`,`POST ${base}/elements`,`GET ${base}/element/hidden/displayed`,`GET ${base}/url`,`GET ${base}/title`,`POST ${base}/execute/sync`]);assert.deepEqual(requests.filter(request=>request.url.endsWith('/elements')).map(request=>request.body),[{using:'css selector',value:'#unique-hidden'}]);
    requests.length=0;await adapter.waitFor('hidden',{by:'css',value:'#transition'},1500);assert.deepEqual(transitionStates,[true,true,false],'wait observes a visible target before its later hidden state');assert.equal(polls.get('#transition'),3);assert.ok(requests.filter(request=>request.url.endsWith('/elements')).every(request=>request.body.using==='css selector'&&request.body.value==='#transition'));
    requests.length=0;await assert.rejects(adapter.waitFor('hidden',{by:'css',value:'#duplicates'},130),error=>error instanceof DesktopAdapterError&&error.code==='REMOTE_COMMAND_FAILED'&&error.message.endsWith('wait condition timed out'));assert.ok((polls.get('#duplicates')??0)>1,'ambiguous targets continue polling');assert.ok(requests.filter(request=>request.url.endsWith('/elements')).every(request=>request.body.using==='css selector'&&request.body.value==='#duplicates'));assert.equal(requests.some(request=>request.url.endsWith('/displayed')),false,'ambiguous targets never select an element for a displayed-state probe');
    requests.length=0;await assert.rejects(adapter.waitFor('hidden',{by:'css',value:'#stale'},500),error=>error instanceof DesktopAdapterError&&error.code==='REMOTE_COMMAND_FAILED');assert.deepEqual(requests.map(({method,url})=>`${method} ${url}`),[`GET ${base}/url`,`POST ${base}/elements`,`GET ${base}/element/stale/displayed`],'stale unique-match probe fails without retry or later status requests');
    assert.equal(allRequests.some(({method,url})=>method==='DELETE'||/\/(?:click|actions|window|screenshot)$/.test(url)||method==='POST'&&url.endsWith('/url')),false,'hidden waits issue no mutation, capture, navigation, or lifecycle requests');assert.equal(adapter.revision,0);assert.deepEqual(adapter.actionSequence(),[]);
  }finally{await new Promise<void>(resolve=>fixture.server.close(()=>resolve()));}
});
